public class MoneyAmountTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        check("of(3, 250).toString()", "$5.50", safe(() -> MoneyAmount.of(3, 250).toString()));
        check("of(3, 250).totalCents()", 550L, safe(() -> MoneyAmount.of(3, 250).totalCents()));
        check("of(-2, 50).toString()", "-$1.50", safe(() -> MoneyAmount.of(-2, 50).toString()));
        check("of(0, 5).toString()", "$0.05", safe(() -> MoneyAmount.of(0, 5).toString()));
        check("of(-2, 50).dollarsPart()", 1L, safe(() -> MoneyAmount.of(-2, 50).dollarsPart()));
        check("of(-2, 50).centsPart()", 50L, safe(() -> MoneyAmount.of(-2, 50).centsPart()));
        check("of(-2, 50).isNegative()", Boolean.TRUE, safe(() -> MoneyAmount.of(-2, 50).isNegative()));
        check("ofCents(0).isNegative()", Boolean.FALSE, safe(() -> MoneyAmount.ofCents(0).isNegative()));
        check("plus", "$20.00",
                safe(() -> MoneyAmount.of(12, 75).plus(MoneyAmount.of(7, 25)).toString()));
        check("minus crossing zero", "-$0.75",
                safe(() -> MoneyAmount.of(1, 0).minus(MoneyAmount.of(1, 75)).toString()));
        check("times", "$29.97",
                safe(() -> MoneyAmount.of(9, 99).times(3).toString()));
        check("times zero", "$0.00", safe(() -> MoneyAmount.of(4, 20).times(0).toString()));
        check("plus leaves the original alone", "$12.75",
                safe(() -> {
                    MoneyAmount base = MoneyAmount.of(12, 75);
                    base.plus(MoneyAmount.of(1, 0));
                    return base.toString();
                }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
