public class MoneyAmount {

    private final long totalCents;

    private MoneyAmount(long totalCents) {
        this.totalCents = totalCents;
    }

    public static MoneyAmount of(long dollars, long cents) {
        return new MoneyAmount(dollars * 100 + cents);
    }

    public static MoneyAmount ofCents(long cents) {
        return new MoneyAmount(cents);
    }

    public long totalCents() {
        return totalCents;
    }

    public long dollarsPart() {
        return Math.abs(totalCents) / 100;
    }

    public long centsPart() {
        return Math.abs(totalCents) % 100;
    }

    public boolean isNegative() {
        return totalCents < 0;
    }

    public MoneyAmount plus(MoneyAmount other) {
        return new MoneyAmount(totalCents + other.totalCents);
    }

    public MoneyAmount minus(MoneyAmount other) {
        return new MoneyAmount(totalCents - other.totalCents);
    }

    public MoneyAmount times(int factor) {
        return new MoneyAmount(totalCents * factor);
    }

    @Override
    public String toString() {
        String sign = isNegative() ? "-" : "";
        return String.format(java.util.Locale.US, "%s$%d.%02d", sign, dollarsPart(), centsPart());
    }
}
